{
  "application": "data-visualization",
  "case_id": "case-health-maternal-mortality-investment-comparison",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "researchers and policy makers",
    "tone": "analytical, narrative-driven, publication-ready"
  },
  "goal": [
    {
      "id": "investment-improvement-narrative",
      "insight": "Visually link each country's health expenditure trajectory with its maternal mortality trend to show how changes in spending correspond to changes in mortality over time"
    },
    {
      "id": "rural-urban-disparity",
      "insight": "Highlight the gap between rural and urban maternal mortality rates for each country, making the magnitude of disparity visually prominent"
    },
    {
      "id": "midwife-coverage-contrast",
      "insight": "Emphasize the variation in skilled birth attendant / midwife coverage across the eight countries and show how higher coverage countries compare in mortality outcomes"
    },
    {
      "id": "top-improvers-spotlight",
      "insight": "Draw attention to the countries that show the steepest decline in maternal mortality over the time period, contrasting them with countries showing slower progress"
    },
    {
      "id": "spending-threshold-pattern",
      "insight": "Show the relationship between health expenditure as a share of GDP and maternal mortality levels across all eight countries and time points"
    }
  ]
}

