arguments.content:
const fs = require('fs');

const data = JSON.parse(fs.readFileSync('/app/benchmark/source_data.json', 'utf8'));
const mmrData = data.maternal_mortality_timeseries.data;
const expData = data.health_expenditure_gdp.data;

// Combine data by country and year
const combined = [];
for (const m of mmrData) {
  const e = expData.find(x => x.country === m.country && x.year === m.year);
  if (e) {
    combined.push({
      country: m.country,
      year: m.year,
      mmr: m.mmr,
      exp: e.health_exp_pct_gdp
    });
  }
}

// Normalize: 
// exp range: 2 to 9 -> (exp - 2) / 7
// mmr range: 0 to 1000 -> mmr / 1000
const normalizeExp = (exp) => (exp - 2) / 7;
const normalizeMmr = (mmr) => mmr / 1000;

let chart = `quadrantChart
  title "Health Expenditure vs. Maternal Mortality (2005 & 2021)"
  x-axis "Low Health Exp. (% GDP)" --> "High Health Exp. (% GDP)"
  y-axis "Low Maternal Mortality" --> "High Maternal Mortality"
  quadrant-1 "High Spending, High Mortality"
  quadrant-2 "Low Spending, High Mortality"
  quadrant-3 "Low Spending, Low Mortality"
  quadrant-4 "High Spending, Low Mortality"
`;

// Just take 2005 and 2021 to avoid too much clutter, or all? The goal says "across all eight countries and time points".
// If I put 40 points, it might be crowded. Let's try 2005, 2013, 2021.
const selectedYears = [2005, 2013, 2021];
for (const item of combined) {
  if (selectedYears.includes(item.year)) {
    const x = normalizeExp(item.exp).toFixed(3);
    const y = normalizeMmr(item.mmr).toFixed(3);
    const yr = item.year.toString().slice(2);
    chart += `  ${item.country} '${yr}: [${x}, ${y}]\n`;
  }
}

fs.writeFileSync('/app/test_quadrant.mmd', chart);
console.log("Done");

